{"content": [{"type": "text", "text": "{"status":"success","path":"outline.json","content":"{\n  \"act_one\": {\n    \"description\": \"建立体操竞技世界观，引入重生的林希和沈清，展现两人因记忆错位产生的冲突和张力。林希重生回到18岁运动员时期，发现队友沈清也重生了，但沈清对她充满恐惧和敌意。\",\n    \"key_chapters\": [\n      {\n        \"chapter_number\": 1,\n        \"chapter_title\": \"重回十八岁\",\n        \"core_event\": \"林希在医院醒来，发现自己重生回到18岁体操运动员时期，立即去体操馆找沈清。\",\n        \"emotional_tone\": \"激动、期待\",\n        \"key_scenes\": [\"林希醒来发现重生\", \"冲向体操馆\", \"第一次见到年轻的沈清\"]\n      },\n      {\n        \"chapter_number\": 2,\n        \"chapter_title\": \"恐惧的眼神\",\n        \"core_event\": \"林希在体操馆找到沈清，却发现沈清看她的眼神充满恐惧和仇恨，沈清拒绝与她接触。\",\n        \"emotional_tone\": \"困惑、受伤\",\n        \"key_scenes\": [\"沈清躲闪林希\", \"沈清的恐惧反应\", \"林希的困惑和心痛\"]\n      },\n      {\n        \"chapter_number\": 3,\n        \"chapter_title\": \"拼命补偿\",\n        \"core_event\": \"林希开始拼命补偿沈清，送营养品、帮训练、甚至主动让出比赛机会，但沈清更加警惕。\",\n        \"emotional_tone\": \"执着、挫败\",\n        \"key_scenes\": [\"林希送营养品被拒\", \"训练中强行帮助\", \"沈清的冷言冷语\"]\n      },\n      {\n        \"chapter_number\": 4,\n        \"chapter_title\": \"意外的发现\",\n        \"core_event\": \"林希在整理旧物时发现前世忽略的线索——平衡木的螺丝有问题，意识到事故不是意外。\",\n        \"emotional_tone\": \"震惊、愧疚\",\n        \"key_scenes\": [\"发现旧体操鞋\", \"看到螺丝松动\", \"回忆前世的疏忽\"]\n      }\n    ],\n    \"turning_point\": \"林希发现事故真相，决定不仅要补偿还要查明真相，而沈清开始怀疑林希的动机不单纯。\"\n  },\n  \"act_two\": {\n    \"description\": \"两人在共同训练中冲突不断升级，林希试图接近真相，沈清的误解加深。中间出现关键转折，两人开始互相理解。\",\n    \"key_chapters\": [\n      {\n        \"chapter_number\": 5,\n        \"chapter_title\": \"训练场上的较量\",\n        \"core_event\": \"队内选拔赛，林希和沈清同场竞技，林希故意放水让沈清赢，却被沈清看穿并羞辱。\",\n        \"emotional_tone\": \"紧张、羞辱\",\n        \"key_scenes\": [\"选拔赛开始\", \"林希故意失误\", \"沈清愤怒质问\"]\n      },\n      {\n        \"chapter_number\": 6,\n        \"chapter_title\": \"深夜的体操馆\",\n        \"core_event\": \"沈清深夜独自加练，林希偷偷观看并发现沈清的腿伤比想象中严重，心疼不已。\",\n        \"emotional_tone\": \"心疼、隐秘\",\n        \"key_scenes\": [\"沈清独自训练\", \"腿伤发作\", \"林希暗中观察\"]\n      },\n      {\n        \"chapter_number\": 7,\n        \"chapter_title\": \"误会加深\",\n        \"core_event\": \"沈清误以为林希在向教练说她坏话，两人爆发激烈争吵，沈清说出'我宁愿瘫痪也不要你的假好心'。\",\n        \"emotional_tone\": \"激烈、绝望\",\n        \"key_scenes\": [\"教练办公室外\", \"激烈争吵\", \"沈清的狠话\"]\n      },\n      {\n        \"chapter_number\": 8,\n        \"chapter_title\": \"真相的碎片\",\n        \"core_event\": \"林希找到前世的队友询问，得知沈清当时是为了救她才冲上平衡木，而道具故障是有人蓄意破坏。\",\n        \"emotional_tone\": \"震撼、愤怒\",\n        \"key_scenes\": [\"询问老队友\", \"得知真相\", \"发现蓄意破坏的线索\"]\n      },\n      {\n        \"chapter_number\": 9,\n        \"chapter_title\": \"第一次合作\",\n        \"core_event\": \"双人训练项目，两人被迫搭档，在空中动作中沈清失衡，林希本能地接住她，两人有了第一次真正的接触。\",\n        \"emotional_tone\": \"紧张、微妙\",\n        \"key_scenes\": [\"双人平衡木\", \"沈清失衡\", \"林希接住\", \"短暂的默契\"]\n      }\n    ],\n    \"turning_point\": \"双人训练中的默契让沈清开始动摇，怀疑自己是否真的了解全部真相，而林希决定直接告诉沈清重生的事实。\"\n  },\n  \"act_three\": {\n    \"description\": \"林希向沈清坦白重生真相，两人解开前世误会，联手查出 sabotage 真相，在比赛中强强联手拿下金牌，感情升温。\",\n    \"key_chapters\": [\n      {\n        \"chapter_number\": 10,\n        \"chapter_title\": \"坦白\",\n        \"core_event\": \"林希在更衣室向沈清坦白自己也重生了，并说出前世沈清为救她而受伤的真相，沈清震惊但开始相信。\",\n        \"emotional_tone\": \"震撼、动摇\",\n        \"key_scenes\": [\"更衣室坦白\", \"说出细节\", \"沈清的震惊和泪水\"]\n      },\n      {\n        \"chapter_number\": 11,\n        \"chapter_title\": \"联手调查\",\n        \"core_event\": \"两人开始暗中调查当年的 sabotage 事件，发现是竞争对手的教练所为，关系进一步拉近。\",\n        \"emotional_tone\": \"默契、信任\",\n        \"key_scenes\": [\"查看监控\", \"发现线索\", \"并肩作战的感觉\"]\n      },\n      {\n        \"chapter_number\": 12,\n        \"chapter_title\": \"情感突破\",\n        \"core_event\": \"沈清腿伤复发，林希彻夜照顾，两人在深夜坦诚相对，沈清承认自己其实一直渴望林希的关心，感情突破。\",\n        \"emotional_tone\": \"温暖、甜蜜\",\n        \"key_scenes\": [\"腿伤复发\", \"林希照顾\", \"深夜谈心\", \"第一次亲密接触\"]\n      },\n      {\n        \"chapter_number\": 13,\n        \"chapter_title\": \"决赛前夕\",\n        \"core_event\": \"全国锦标赛决赛前， sabotage 者试图再次动手脚，被两人识破并反制，两人的默